import{_ as r,l as o,o as a,c as p,v as l,p as s,x as i,d as n,i as c,S as h}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"薄膜寿命与更换","description":"","frontmatter":{"title":"薄膜寿命与更换","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/pellicle-lifetime.md","filePath":"litho/pellicle-lifetime.md","lastUpdated":1789023840000}'),d={name:"litho/pellicle-lifetime.md"};function E(m,e,_,f,A,u){const t=o("Mermaid");return a(),p("div",null,[e[1]||(e[1]=l('<h1 id="薄膜寿命与更换" tabindex="-1">薄膜寿命与更换 <a class="header-anchor" href="#薄膜寿命与更换" aria-label="Permalink to &quot;薄膜寿命与更换&quot;">​</a></h1><div class="epigraph"><p>pellicle 的合同是透过率、皱纹和破膜率随脉冲累积而变。寿命到点必须更换，不是把 DUV 有机膜的年计寿命搬过来。</p><footer>—— 据 ASML 对 EUV pellicle 功率、透过率与更换的公开讨论</footer></div><p><a href="/litho/euv-mask-repair">上一课</a>把版面缺陷修到光化可过。缺口是版上那张膜：<a href="/litho/euv-pellicle">EUV pellicle</a> 已经写过双程 \\(T^2\\) 和热；本课钉寿命与更换节奏。无膜硬跑的风险，留给[下一课](/litho/pellicle-free-risk）。不重写 DUV 薄膜安装产线。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>修复课假设图形面可接近。装上 pellicle 之后，再修要先揭膜，产尘和破膜风险上升。更日常的是：膜在数百瓦级热流和氢、EUV 下老化——透过率掉、均匀性变、应力致皱、最后破。破膜碎片落在多层上，比从未装膜更糟。功率路线往 500 W、1 kW 走，膜的吸收功率密度先于版本身到达极限。</p><p>缺口是把 pellicle 当消耗品记账：何时换、换的时候机台停多久、透过率漂移如何进剂量。不是再论证「要不要膜」。</p><p><span class="marginnote">DUV pellicle 更换周期可以很长。EUV 膜的寿命与源功率绑定，必须按层别和 IF 瓦数分层，不能写一张全厂年历。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>监测：在线或下机测平均 \\(T\\)、空间指纹、热鼓包干涉图、破洞检测联锁。阈值：剂量补偿加不到、CD 指纹超 SPC、或破膜风险不可接受时更换。物流：膜框与掩模台、机械手兼容，拆装在特定洁净流程，背面颗粒课的接触点约束同样适用。</p><p>CNT 等高透过路线的公开目标是扛更高功率、更长寿命；资格认证仍以扫描机气体与功率为准，不能只用可见光 \\(T\\)。更换时的剂量配方要重标定，因为新膜 \\(T^2\\) 不同。</p><h3 id="透过率漂移要进剂量环-不要只进日历" tabindex="-1">透过率漂移要进剂量环，不要只进日历 <a class="header-anchor" href="#透过率漂移要进剂量环-不要只进日历" aria-label="Permalink to &quot;透过率漂移要进剂量环，不要只进日历&quot;">​</a></h3><p>平均 \\(T\\) 慢降，剂量环可以加扫描时间或源功率。空间指纹和皱纹环补不了，CD 图会先于平均剂量越界。更换判据因此是指纹 SPC，不是「满多少天」。功率爬坡试验必须单独做寿命，250 W 合格不代表下一档 IF 仍合格。</p>',12)),(a(),s(h,null,{default:i(()=>[c(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20PWR%5B%22IF%20%E5%8A%9F%E7%8E%87%E4%B8%8E%E6%B0%A2%22%5D%20--%3E%20AGE%5B%22T%20%E4%B8%8B%E9%99%8D%20%2F%20%E8%B5%B7%E7%9A%B1%22%5D%0A%20%20AGE%20--%3E%20DOSE%5B%22%E5%89%82%E9%87%8F%E8%A1%A5%E5%81%BF%22%5D%0A%20%20AGE%20--%3E%20SWAP%5B%22%E6%9B%B4%E6%8D%A2%20pellicle%22%5D%0A%20%20BRK%5B%22%E7%A0%B4%E8%86%9C%22%5D%20--%3E%20LOCK%5B%22%E8%81%94%E9%94%81%E5%81%9C%E6%9C%BA%22%5D%0A%20%20LOCK%20--%3E%20SWAP%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=l('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>吸收功率加热膜，真空中靠辐射和框导热。温度循环疲劳、氢刻蚀某些成分、EUV 断键，使应力和孔隙率变，\\(T\\) 和相位指纹变成时间函数。OPC 静态层修不了这张时变图。破膜是应力或热点超过强度，碎片尺寸足以打印。联锁必须快过下一场扫描。</p><p><span class="marginnote">寿命用脉冲数或曝光场数代理，必须声明功率。250 W 下的寿命不能外推到未过滤的 1 kW。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把「无 pellicle 策略」写成推荐，下一课才写风险。不重写 <a href="/litho/pellicle-mount-inspect">薄膜安装与检验</a> 的 DUV 厂流程。更换是计划停机，破膜是故障停机，稼动账必须分开。出处：ASML EUV pellicle；Bakshi 膜热与透过；pellicle 原理课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>EUV pellicle 是功率相关消耗品，透过率漂移进剂量，破膜是灾难项。</li><li>更换与揭膜修复绑定，要进稼动计划。</li><li>下一课：不装膜时颗粒与产能怎么权衡。</li><li>出处：ASML pellicle 公开材料；Bakshi。</li></ul>',7))])}const D=r(d,[["render",E]]);export{T as __pageData,D as default};
